// Normalize any incoming payload (website form, email webhook, chat widget)
// into one clean ticket. Accepts JSON or form-encoded bodies.
const items = $input.all();
return items.map((item) => {
  const src = (item.json.body && typeof item.json.body === 'object') ? item.json.body : item.json;
  const pick = (...keys) => {
    for (const k of keys) {
      const v = src[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };
  const rand = Math.random().toString(36).slice(2, 6).toUpperCase();
  return {
    json: {
      ticket_id: 'T-' + Date.now().toString(36).toUpperCase() + '-' + rand,
      received_at: new Date().toISOString(),
      channel: pick('channel') || 'webhook',
      name: pick('name', 'Name', 'from_name') || 'there',
      email: pick('email', 'Email', 'from'),
      subject: pick('subject', 'Subject'),
      message: pick('message', 'Message', 'text', 'content').slice(0, 4000),
      external_id: pick('id', 'external_id', 'test_id'),
    },
  };
});

// Build the Claude Messages API request. The API key is NOT here:
// the HTTP node reads it from the ANTHROPIC_API_KEY environment variable.
const msg = $('Normalize message').first().json;
const kb = ((j) => j.data && j.data.faqs ? j.data : j)($('Parse FAQ file').first().json);
const faqList = kb.faqs.map((f) => `- ${f.id}: ${f.question}`).join('\n');

const system = [
  `You are the inbox triage assistant for ${kb.company}.`,
  'Classify the customer message into exactly one category:',
  '- question: the customer asks for information (shipping, returns, payment, tracking, sizes, warranty, contact).',
  '- order: the customer wants to buy / place / change an order or asks for a quote.',
  '- complaint: the customer is unhappy (damaged, late, wrong item, bad service) or demands a refund.',
  '- spam: unsolicited marketing, SEO/crypto offers, phishing, gibberish.',
  'If it is a question, pick the best matching FAQ id from this list, or null if none fits:',
  faqList,
  'Return only JSON with keys: category, confidence (0-1), faq_id, summary (max 15 words).',
].join('\n');

const request = {
  model: $env.AI_MODEL || 'claude-opus-5-5',
  max_tokens: 2048,
  system,
  output_config: {
    effort: 'low',
    format: {
      type: 'json_schema',
      schema: {
        type: 'object',
        additionalProperties: false,
        required: ['category', 'confidence', 'faq_id', 'summary'],
        properties: {
          category: { type: 'string', enum: ['question', 'order', 'complaint', 'spam'] },
          confidence: { type: 'number' },
          faq_id: { type: ['string', 'null'] },
          summary: { type: 'string' },
        },
      },
    },
  },
  messages: [
    { role: 'user', content: `Subject: ${msg.subject || '(none)'}\nFrom: ${msg.name} <${msg.email}>\n\n${msg.message}` },
  ],
};
return [{ json: { request } }];

// Parse Claude's JSON answer. Any problem -> throw, and the error output
// routes the ticket to the rules-based classifier instead.
const res = $input.first().json;
if (res.stop_reason === 'refusal') throw new Error('AI refused');
const textBlock = (res.content || []).find((b) => b.type === 'text');
if (!textBlock) throw new Error('No text block in AI response');
const raw = textBlock.text.trim();
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
const parsed = JSON.parse(raw.slice(start, end + 1));
const allowed = ['question', 'order', 'complaint', 'spam'];
if (!allowed.includes(parsed.category)) throw new Error('Unknown category: ' + parsed.category);
return [{
  json: {
    category: parsed.category,
    confidence: Math.max(0, Math.min(1, Number(parsed.confidence) || 0.5)),
    faq_id: parsed.faq_id || null,
    summary: parsed.summary || '',
    classifier: 'ai:' + (res.model || 'claude'),
  },
}];

// Rules-based classifier: used when no ANTHROPIC_API_KEY is set
// or when the AI call fails. Deterministic, free, works offline (EN + DE).
const msg = $('Normalize message').first().json;
const text = `${msg.subject} ${msg.message}`.toLowerCase();
const count = (patterns) => patterns.reduce((n, re) => n + (re.test(text) ? 1 : 0), 0);

const spamHits = count([
  /\b(seo|backlinks?|guest post|rank #?1|first page of google)\b/,
  /\b(crypto|bitcoin|forex|investment opportunity|double your)\b/,
  /\b(casino|lottery|you (have )?won|winner|prize|claim your)\b/,
  /\b(cheap followers|buy followers|click here|limited offer|act now)\b/,
  /(bit\.ly|tinyurl|https?:\/\/\S+\.(ru|xyz|top)\b)/,
  /\$\d{3,}|\b100% free\b|!!!/,
]) + ((text.match(/https?:\/\//g) || []).length >= 2 ? 1 : 0);

const complaintHits = count([
  /\b(complain|complaint|disappointed|unacceptable|terrible|awful|worst|horrible|furious|angry)\b/,
  /\b(broken|damaged|defective|faulty|torn|wrong (item|size|colou?r)|missing)\b/,
  /(never arrived|still (haven'?t|hasn'?t|not) (received|arrived)|been waiting|weeks? late|no one (answers|replies))/,
  /\b(refund (me|now|immediately)|money back|chargeback|lawyer|scam)\b/,
  /\b(beschwerde|kaputt|beschädigt|enttäuscht|unverschämt|frechheit)\b/,
]);

const orderHits = count([
  /\b(i('d| would) like to (order|buy|purchase)|i want to (order|buy|purchase)|place an order|can i order)\b/,
  /\b(please send me|i('ll| will) take|add to my order|quote for|bulk order|wholesale)\b/,
  /\b\d+\s?(x|pcs|pieces|units|pairs)\b/,
  /\b(ich möchte .*(bestellen|kaufen)|bestellung aufgeben|ich bestelle)\b/,
]);

const questionHits = count([
  /\?/,
  /\b(how|what|when|where|which|do you|can i|is there|is it|are there)\b/,
  /\b(wie|wann|wo|was|welche|gibt es|kann ich)\b/,
]);

let category = 'question';
let hits = questionHits;
if (spamHits >= 2) { category = 'spam'; hits = spamHits; }
else if (complaintHits >= 1) { category = 'complaint'; hits = complaintHits; }
else if (orderHits >= 1) { category = 'order'; hits = orderHits; }

const confidence = hits === 0 ? 0.35 : Math.min(0.95, 0.55 + 0.15 * hits);
return [{ json: { category, confidence: Number(confidence.toFixed(2)), faq_id: null, summary: '', classifier: 'rules' } }];

// Pick the answer from the knowledge base and decide who handles the ticket.
// Replies are built ONLY from the FAQ file - the AI never invents policies.
const msg = $('Normalize message').first().json;
const kb = ((j) => j.data && j.data.faqs ? j.data : j)($('Parse FAQ file').first().json);
const cls = $input.first().json;
const text = `${msg.subject} ${msg.message}`.toLowerCase();

// FAQ match: the AI's pick if valid, otherwise the best keyword score.
let faq = kb.faqs.find((f) => f.id === cls.faq_id) || null;
if (!faq) {
  let best = 0;
  for (const f of kb.faqs) {
    const score = f.keywords.reduce((n, k) => n + (text.includes(k.toLowerCase()) ? k.split(' ').length : 0), 0);
    if (score > best) { best = score; faq = f; }
  }
}

const hello = `Hi ${msg.name},\n\n`;
const bye = `\n\nBest regards,\n${kb.signature}\n\n${kb.ai_disclosure}`;
let reply = '';
let escalate = false;
let reason = '';
let priority = 'normal';
let status = 'auto_replied';

switch (cls.category) {
  case 'question':
    if (faq && cls.confidence >= 0.5) {
      reply = hello + faq.answer + bye;
    } else {
      reply = hello + kb.templates.unknown + bye;
      escalate = true; reason = 'no_confident_answer'; status = 'handoff_to_human';
    }
    break;
  case 'order':
    reply = hello + kb.templates.order + bye;
    status = 'order_logged';
    break;
  case 'complaint':
    reply = hello + kb.templates.complaint + bye;
    escalate = true; reason = 'complaint'; priority = 'high'; status = 'escalated';
    break;
  case 'spam':
    status = 'ignored_spam';
    break;
}

const faqId = cls.category === 'question' && faq ? faq.id : '';
return [{
  json: {
    ...msg,
    category: cls.category,
    confidence: cls.confidence,
    classifier: cls.classifier,
    faq_id: faqId,
    reply,
    escalate,
    escalation_reason: reason,
    priority,
    status,
    response: {
      ticket_id: msg.ticket_id,
      category: cls.category,
      confidence: cls.confidence,
      classifier: cls.classifier,
      faq_id: faqId || null,
      escalated: escalate,
      status,
      reply,
    },
  },
}];

// Turn the ticket into one CSV line (the "Google Sheets" stub).
// In production replace this + the next node with a Google Sheets "Append row" node.
const t = $input.first().json;
const cols = [t.ticket_id, t.received_at, t.channel, t.name, t.email, t.category, t.confidence,
  t.classifier, t.faq_id, t.escalate ? 'yes' : 'no', t.status, t.message, t.reply];
const esc = (v) => '"' + String(v ?? '').replace(/\r?\n/g, ' / ').replace(/"/g, '""') + '"';
const line = cols.map(esc).join(',') + '\n';
return [{
  json: t,
  binary: { data: { data: Buffer.from(line, 'utf8').toString('base64'), mimeType: 'text/csv', fileName: 'tickets.csv', fileExtension: 'csv' } },
}];

// Manager notification (stub): one JSON line per escalated ticket.
// In production swap the next node for Telegram / Slack / Gmail.
const t = $('Build reply').first().json;
const kb = ((j) => j.data && j.data.faqs ? j.data : j)($('Parse FAQ file').first().json);
const alert = {
  sent_at: new Date().toISOString(),
  to: kb.manager_contact,
  priority: t.priority,
  reason: t.escalation_reason,
  ticket_id: t.ticket_id,
  customer: `${t.name} <${t.email}>`,
  subject: `[${t.priority.toUpperCase()}] ${t.category} from ${t.name}`,
  message: t.message,
};
const line = JSON.stringify(alert) + '\n';
return [{
  json: alert,
  binary: { data: { data: Buffer.from(line, 'utf8').toString('base64'), mimeType: 'application/json', fileName: 'manager_alerts.jsonl', fileExtension: 'jsonl' } },
}];
